55	  }
56	  li:first-child { margin-top: 0; }
57	  .priority { flex: none; padding: 2px 8px; border-radius: 999px; font-size: 12px; font-weight: 600; background: #e3e3e8; color: #5e5e63; }
58	  .content { flex: 1; min-width: 0; }
