62	  li[data-overdue="true"] { box-shadow: inset 3px 0 0 #d70015; }
63	  li[data-overdue="true"] .due { color: #d70015; font-weight: 600; }
64	  li[data-overdue="true"][data-completed="true"] { box-shadow: inset 3px 0 0 #f2b8bd; }
