67	  .delete:hover { background: rgba(215, 0, 21, 0.1); color: #d70015; }
68	  .empty { margin: 16px 0 0; color: #86868b; text-align: center; }
69	  .toggle { width: 18px; height: 18px; margin: 0; flex: none; cursor: pointer; accent-color: #0071e3; }
70	  li[data-completed="true"] .text { color: #86868b; text-decoration: line-through; }
71	  .filters { display: flex; gap: 4px; margin: 16px 0 0; }
72	  .filter { padding: 6px 12px; background: transparent; color: #1d1d1f; font-size: 14px; }
