77	<body>
78	<main>
79	  <h1>Todos</h1>
80	  <form id="todo-form" autocomplete="off">
81	    <input type="text" data-testid="todo-input" id="todo-input" placeholder="What needs doing?" aria-label="New todo">
82	    <input type="date" data-testid="todo-due" id="todo-due" aria-label="Due date (optional)">
83	    <select data-testid="todo-priority" id="todo-priority" aria-label="Priority">
84	      <option value="low">Low</option>
85	      <option value="med" selected>Med</option>
86	      <option value="high">High</option>
87	    </select>
88	    <button type="submit" class="add" data-testid="todo-add">Add</button>
89	  </form>
90	  <div class="filters" role="group" aria-label="Show">
91	    <button type="button" class="filter" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
92	    <button type="button" class="filter" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
93	    <button type="button" class="filter" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
94	  </div>
95	  <ul data-testid="todo-list" id="todo-list"></ul>
96	  <p class="empty" id="empty">Nothing here yet.</p>
97	</main>
98	<script>
99	(function () {
100	  var STORAGE_KEY = 'todos';
101	
102	  var form = document.getElementById('todo-form');
103	  var input = document.getElementById('todo-input');
104	  var dueInput = document.getElementById('todo-due');
105	  var priorityInput = document.getElementById('todo-priority');
106	  var list = document.getElementById('todo-list');
107	  var empty = document.getElementById('empty');
108	  var filterButtons = document.querySelectorAll('[data-filter]');
109	
110	  var filter = 'all';
111	
112	  function load() {
113	    try {
114	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
115	      return Array.isArray(data) ? data : [];
116	    } catch (e) {
117	      return [];
118	    }
119	  }
120	
121	  function save() {
122	    try {
123	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
124	    } catch (e) {
125	      // Storage unavailable or full; keep working in memory.
126	    }
127	  }
128	
129	  function newId() {
130	    if (window.crypto && typeof crypto.randomUUID === 'function') {
131	      return crypto.randomUUID();
132	    }
133	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
134	  }
135	
136	  var todos = load();
137	
138	  // Date rule (project decision): a due date is stored as a plain "YYYY-MM-DD"
139	  // string and means a LOCAL calendar date. Never pass it through Date parsing
140	  // or UTC (new Date("YYYY-MM-DD") is UTC midnight and shifts the day).
141	  // Overdue = due date strictly before today's local date; date-only, so a
142	  // todo due today is never overdue. Zero-padded strings compare correctly as text.
143	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
144	
145	  function pad(n) {
146	    return (n < 10 ? '0' : '') + n;
147	  }
148	
149	  function todayLocal() {
150	    var now = new Date();
151	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
152	  }
153	
154	  function validDue(value) {
155	    return typeof value === 'string' && DATE_RE.test(value) ? value : null;
156	  }
157	
158	  function isOverdue(todo) {
159	    var due = validDue(todo.due);
160	    return due !== null && due < todayLocal();
161	  }
162	
163	  // Priority rule: one of "low", "med", "high". Anything else (including todos
164	  // saved before priorities existed) is treated as "med".
165	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
166	
167	  function validPriority(value) {
168	    return PRIORITY_LABELS.hasOwnProperty(value) ? value : 'med';
169	  }
170	
171	  function formatDue(due) {
172	    var parts = due.split('-');
173	    var year = Number(parts[0]);
174	    var date = new Date(year, Number(parts[1]) - 1, Number(parts[2])); // Local date.
175	    var options = { month: 'short', day: 'numeric' };
176	    if (year !== new Date().getFullYear()) options.year = 'numeric';
177	    return date.toLocaleDateString(undefined, options);
178	  }
179	
180	  // Ordering rule (project decision): completed todos always appear below all
181	  // active todos. Within each group, todos are sorted by priority (high, med,
182	  // low); within the same priority they stay in insertion order (oldest first).
183	  // `todos` is kept in insertion order; the index tiebreak keeps the sort stable.
184	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
185	
186	  function byPriority(group) {
187	    return group
188	      .map(function (t, i) { return { todo: t, index: i }; })
189	      .sort(function (a, b) {
190	        return PRIORITY_RANK[validPriority(a.todo.priority)] - PRIORITY_RANK[validPriority(b.todo.priority)] ||
191	          a.index - b.index;
192	      })
193	      .map(function (entry) { return entry.todo; });
194	  }
195	
196	  function ordered() {
197	    var active = todos.filter(function (t) { return !t.completed; });
198	    var completed = todos.filter(function (t) { return t.completed; });
199	    return byPriority(active).concat(byPriority(completed));
200	  }
201	
202	  function visible() {
203	    return ordered().filter(function (t) {
204	      if (filter === 'active') return !t.completed;
205	      if (filter === 'completed') return !!t.completed;
206	      return true;
207	    });
208	  }
209	
210	  // Rows are kept by id and reused across renders, so a checkbox the user just
211	  // clicked stays the same element after the list is reordered or filtered.
212	  var rows = {};
213	
214	  function createRow(todo) {
215	    var li = document.createElement('li');
216	    li.setAttribute('data-testid', 'todo-item');
217	    li.setAttribute('data-id', todo.id);
218	
219	    var toggle = document.createElement('input');
220	    toggle.type = 'checkbox';
221	    toggle.className = 'toggle';
222	    toggle.setAttribute('data-testid', 'todo-toggle');
223	    toggle.addEventListener('change', function () {
224	      toggleTodo(todo.id);
225	    });
226	
227	    var content = document.createElement('div');
228	    content.className = 'content';
229	
230	    var text = document.createElement('span');
231	    text.className = 'text';
232	    text.setAttribute('data-testid', 'todo-text');
233	    text.textContent = todo.text;
234	
235	    var due = document.createElement('time');
236	    due.className = 'due';
237	    due.setAttribute('data-testid', 'todo-due-date');
238	
239	    content.appendChild(text);
240	    content.appendChild(due);
241	
242	    var priority = document.createElement('span');
243	    priority.className = 'priority';
244	
245	    var del = document.createElement('button');
246	    del.type = 'button';
247	    del.className = 'delete';
248	    del.setAttribute('data-testid', 'todo-delete');
249	    del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
250	    del.textContent = 'Delete';
251	    del.addEventListener('click', function () {
252	      removeTodo(todo.id);
253	    });
254	
255	    li.appendChild(toggle);
256	    li.appendChild(content);
257	    li.appendChild(priority);
258	    li.appendChild(del);
259	    return li;
260	  }
261	
262	  function render() {
263	    var items = visible();
264	    var keep = {};
265	
266	    items.forEach(function (todo) {
267	      var li = rows[todo.id] || (rows[todo.id] = createRow(todo));
268	      var toggle = li.querySelector('.toggle');
269	      var dueLabel = li.querySelector('.due');
270	      var due = validDue(todo.due);
271	      var overdue = isOverdue(todo);
272	      var priority = validPriority(todo.priority);
273	      var priorityLabel = li.querySelector('.priority');
274	      li.setAttribute('data-priority', priority);
275	      priorityLabel.textContent = PRIORITY_LABELS[priority];
276	      priorityLabel.setAttribute('aria-label', PRIORITY_LABELS[priority] + ' priority');
277	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
278	      li.setAttribute('data-overdue', overdue ? 'true' : 'false');
279	      dueLabel.hidden = due === null;
280	      if (due === null) {
281	        dueLabel.removeAttribute('datetime');
282	        dueLabel.textContent = '';
283	      } else {
284	        dueLabel.setAttribute('datetime', due);
285	        dueLabel.textContent = (overdue ? 'Overdue \u00b7 ' : 'Due ') + formatDue(due);
286	      }
287	      toggle.checked = !!todo.completed;
288	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" as ' + (todo.completed ? 'not done' : 'done'));
289	      keep[todo.id] = true;
290	      list.appendChild(li); // Moves an existing row into place.
291	    });
292	
293	    Object.keys(rows).forEach(function (id) {
294	      if (keep[id]) return;
295	      if (rows[id].parentNode) rows[id].parentNode.removeChild(rows[id]);
296	      if (!todos.some(function (t) { return t.id === id; })) delete rows[id];
297	    });
298	
299	    filterButtons.forEach(function (button) {
300	      button.setAttribute('aria-pressed', button.getAttribute('data-filter') === filter ? 'true' : 'false');
301	    });
302	
303	    if (todos.length === 0) {
304	      empty.textContent = 'Nothing here yet.';
305	    } else if (filter === 'active') {
306	      empty.textContent = 'All done.';
307	    } else if (filter === 'completed') {
308	      empty.textContent = 'Nothing completed yet.';
309	    }
310	    empty.hidden = items.length > 0;
311	  }
312	
313	  function addTodo(text, due, priority) {
314	    todos.push({ id: newId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: validPriority(priority) });
315	    save();
316	    render();
317	  }
318	
319	  function removeTodo(id) {
320	    todos = todos.filter(function (t) { return t.id !== id; });
321	    save();
322	    render();
323	  }
324	
325	  function toggleTodo(id) {
326	    todos.forEach(function (t) {
327	      if (t.id === id) t.completed = !t.completed;
328	    });
329	    save();
330	    render();
331	  }
332	
333	  function setFilter(value) {
334	    filter = value;
335	    render();
336	  }
337	
338	  filterButtons.forEach(function (button) {
339	    button.addEventListener('click', function () {
340	      setFilter(button.getAttribute('data-filter'));
341	    });
342	  });
343	
344	  form.addEventListener('submit', function (event) {
345	    event.preventDefault();
346	    var text = input.value.trim();
347	    if (!text) return;
348	    addTodo(text, validDue(dueInput.value), priorityInput.value);
349	    input.value = '';
350	    dueInput.value = '';
351	    priorityInput.value = 'med';
352	    input.focus();
353	  });
354	
355	  // "Today" moves at local midnight; re-render so overdue flags stay current.
356	  function scheduleMidnightRender() {
357	    var now = new Date();
358	    var next = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
359	    setTimeout(function () {
360	      render();
361	      scheduleMidnightRender();
362	    }, next - now + 1000);
363	  }
364	
365	  document.addEventListener('visibilitychange', function () {
366	    if (!document.hidden) render();
367	  });
368	
369	  render();
370	  scheduleMidnightRender();
371	})();
372	</script>
373	</body>
374	</html>
